  5	public final class Graph {
  6	    private final List<List<Integer>> adjacencyList;
  7	
  8	    private Graph(List<List<Integer>> adjacencyList) {
  9	        this.adjacencyList = adjacencyList;
 10	    }
 11	
 12	    public static Graph fromEdges(int vertexCount, int[][] edges) {
 13	        validateInputs(vertexCount, edges);
 14	
 15	        List<List<Integer>> adjacencyList = initializeAdjacencyList(vertexCount);
 16	        for (int[] edge : edges) {
 17	            addUndirectedEdge(adjacencyList, edge[0], edge[1]);
 18	        }
 19	
 20	        return new Graph(toUnmodifiableAdjacencyList(adjacencyList));
 21	    }
 22	
 23	    public int vertexCount() {
 24	        return adjacencyList.size();
 25	    }
 26	
 27	    public List<Integer> neighborsOf(int vertex) {
 28	        validateVertexIndex(vertex);
 29	        return adjacencyList.get(vertex);
 30	    }
 31	
 32	    private static List<List<Integer>> initializeAdjacencyList(int vertexCount) {
 33	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
 34	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 35	            adjacencyList.add(new ArrayList<>());
 36	        }
 37	
 38	        return adjacencyList;
 39	    }
 40	
 41	    private static void addUndirectedEdge(
 42	            List<List<Integer>> adjacencyList,
 43	            int source,
 44	            int destination) {
 45	        adjacencyList.get(source).add(destination);
 46	        adjacencyList.get(destination).add(source);
 47	    }
 48	
 49	    private static List<List<Integer>> toUnmodifiableAdjacencyList(
 50	            List<List<Integer>> adjacencyList) {
 51	        List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
 52	        for (List<Integer> neighbors : adjacencyList) {
 53	            immutableAdjacencyList.add(Collections.unmodifiableList(neighbors));
 54	        }
 55	
 56	        return Collections.unmodifiableList(immutableAdjacencyList);
 57	    }
 58	
 59	    private static void validateInputs(int vertexCount, int[][] edges) {
 60	        if (vertexCount < 0) {
 61	            throw new IllegalArgumentException("Vertex count cannot be negative.");
 62	        }
 63	
 64	        if (edges == null) {
 65	            throw new IllegalArgumentException("Edges cannot be null.");
 66	        }
 67	
 68	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
 69	            validateEdge(edges[edgeIndex], vertexCount, edgeIndex);
 70	        }
 71	    }
 72	
 73	    private static void validateEdge(int[] edge, int vertexCount, int edgeIndex) {
 74	        if (edge == null || edge.length != 2) {
 75	            throw new IllegalArgumentException(
 76	                    "Each edge must contain exactly two vertices. Invalid edge at index "
 77	                            + edgeIndex
 78	                            + ".");
 79	        }
 80	
 81	        validateVertex(edge[0], vertexCount, edgeIndex);
 82	        validateVertex(edge[1], vertexCount, edgeIndex);
 83	    }
